# app/evaluation/eval_merge_role_summary.py

import json
import pandas as pd


# ============================================================
# FILE CONFIGURATION
# ============================================================

# QA dataset generated by evaluate_rag.py
QA_FILE = "qa_pairs_gemini.csv"

# RAG evaluation results generated by evaluate_rag.py
EVALUATION_FILE = "evaluation_results_gemini.csv"

# Final merged file containing role + metrics
OUTPUT_FILE = "final_eval_with_roles.csv"


# ============================================================
# LOAD DATA
# ============================================================

def load_evaluation_data():
    """
    Load the QA dataset and evaluation results.

    QA dataset contains:
        question
        answer
        role
        source

    Evaluation dataset contains:
        question
        prediction
        ground_truth
        contexts
        metrics
    """

    print("Loading QA dataset...")
    qa_df = pd.read_csv(QA_FILE)

    print("Loading evaluation results...")
    eval_df = pd.read_csv(EVALUATION_FILE)

    return qa_df, eval_df


# ============================================================
# MERGE ROLE INFORMATION
# ============================================================

def merge_role_information(
    qa_df,
    eval_df
):
    """
    Add role and source information from the QA dataset
    to the evaluation results.

    The question column is used as the common key.
    """

    # Only take the columns we need from QA dataset.
    role_df = qa_df[
        [
            "question",
            "role",
            "source"
        ]
    ]

    # Merge using question as the common column.
    merged_df = pd.merge(
        eval_df,
        role_df,
        on="question",
        how="left",
        suffixes=("", "_qa")
    )

    return merged_df


# ============================================================
# EXTRACT ONE METRIC
# ============================================================

def extract_metric(
    metrics_text,
    metric_name
):
    """
    Extract one metric from the JSON stored in
    the 'metrics' CSV column.

    Example:

    metrics_text =
    '{"faithfulness": 0.9, "relevancy": 0.8}'

    metric_name =
    'faithfulness'

    returns:

    0.9
    """

    try:

        # Convert JSON string into Python dictionary.
        metrics = json.loads(
            metrics_text
        )

        # Return requested metric.
        return metrics.get(
            metric_name
        )

    except Exception:

        # Return None if JSON is invalid.
        return None


# ============================================================
# EXTRACT ALL METRICS
# ============================================================

def add_metric_columns(
    merged_df
):
    """
    Convert the JSON metrics column into
    separate DataFrame columns.
    """

    # Extract faithfulness score.
    merged_df["faithfulness"] = merged_df[
        "metrics"
    ].apply(
        lambda value: extract_metric(
            value,
            "faithfulness"
        )
    )

    # Extract relevancy score.
    merged_df["relevancy"] = merged_df[
        "metrics"
    ].apply(
        lambda value: extract_metric(
            value,
            "relevancy"
        )
    )

    # Extract context recall score.
    merged_df["context_recall"] = merged_df[
        "metrics"
    ].apply(
        lambda value: extract_metric(
            value,
            "context_recall"
        )
    )

    return merged_df


# ============================================================
# OVERALL SUMMARY
# ============================================================

def calculate_overall_summary(
    merged_df
):
    """
    Calculate average metrics across all evaluation questions.
    """

    # Keep only rows where all three metrics exist.
    valid_df = merged_df.dropna(
        subset=[
            "faithfulness",
            "relevancy",
            "context_recall"
        ]
    )

    # Calculate the average of each metric.
    summary = valid_df[
        [
            "faithfulness",
            "relevancy",
            "context_recall"
        ]
    ].mean()

    print("\n========================================")
    print("       OVERALL RAG EVALUATION")
    print("========================================")

    print(
        f"Faithfulness    : "
        f"{summary['faithfulness']:.2f}"
    )

    print(
        f"Relevancy       : "
        f"{summary['relevancy']:.2f}"
    )

    print(
        f"Context Recall  : "
        f"{summary['context_recall']:.2f}"
    )

    print(
        f"Evaluated Rows  : "
        f"{len(valid_df)}"
    )

    return summary


# ============================================================
# ROLE-BASED SUMMARY
# ============================================================

def calculate_role_summary(
    merged_df
):
    """
    Calculate average RAG metrics separately for every role.
    """

    # Remove rows where role or metrics are missing.
    valid_df = merged_df.dropna(
        subset=[
            "role",
            "faithfulness",
            "relevancy",
            "context_recall"
        ]
    )

    # Group evaluation records by role.
    role_summary = valid_df.groupby(
        "role"
    )[
        [
            "faithfulness",
            "relevancy",
            "context_recall"
        ]
    ].mean()

    # Round the scores for readable output.
    role_summary = role_summary.round(2)

    print("\n========================================")
    print("       ROLE-BASED RAG EVALUATION")
    print("========================================")

    print(role_summary)

    return role_summary


# ============================================================
# SAVE FINAL MERGED DATASET
# ============================================================

def save_final_results(
    merged_df
):
    """
    Save the complete evaluation dataset.

    This file contains:
    - question
    - prediction
    - ground truth
    - contexts
    - role
    - source
    - metrics
    - individual metric columns
    """

    merged_df.to_csv(
        OUTPUT_FILE,
        index=False
    )

    print(
        f"\nFinal merged evaluation file saved to: "
        f"{OUTPUT_FILE}"
    )


# ============================================================
# MAIN
# ============================================================

if __name__ == "__main__":

    # --------------------------------------------------------
    # STEP 1:
    # Load both CSV files.
    # --------------------------------------------------------

    qa_df, eval_df = load_evaluation_data()

    print(
        f"QA records: {len(qa_df)}"
    )

    print(
        f"Evaluation records: {len(eval_df)}"
    )

    # --------------------------------------------------------
    # STEP 2:
    # Merge role/source into evaluation results.
    # --------------------------------------------------------

    merged_df = merge_role_information(
        qa_df,
        eval_df
    )

    # --------------------------------------------------------
    # STEP 3:
    # Extract individual metrics.
    # --------------------------------------------------------

    merged_df = add_metric_columns(
        merged_df
    )

    # --------------------------------------------------------
    # STEP 4:
    # Calculate overall metrics.
    # --------------------------------------------------------

    calculate_overall_summary(
        merged_df
    )

    # --------------------------------------------------------
    # STEP 5:
    # Calculate role-wise metrics.
    # --------------------------------------------------------

    calculate_role_summary(
        merged_df
    )

    # --------------------------------------------------------
    # STEP 6:
    # Save final merged results.
    # --------------------------------------------------------

    save_final_results(
        merged_df
    )

    print(
        "\nEvaluation analysis completed successfully."
    )